-- Source-verified guides and corrected quick answers share the canonical help table.
-- Stable slugs preserve existing IDs; updated answers are immediately used by AI.
INSERT INTO public.help_faqs (slug,feature_area,audience,question,answer_short,answer_long,route,search_terms,priority,requires_admin,is_active,last_verified_at,article_type,read_minutes,related_slugs,source_key)
SELECT slug,feature_area,audience,question,answer_short,answer_long,route,search_terms,priority,requires_admin,is_active,last_verified_at,article_type,read_minutes,related_slugs,source_key
FROM jsonb_to_recordset($articles$[{"slug":"guide-mobile-navigation","feature_area":"Help & Support","audience":"all","question":"Using FuzedFlow on a phone or tablet","answer_short":"Use the mobile navigation built for your role, and open More for less frequent permitted pages and portal sections.","answer_long":"## Use the office bottom navigation\nOwners, administrators, managers, and office staff use a five-action bottom bar on phones instead of a hamburger drawer. Open **Dashboard**, **Leads**, **Projects**, or **Tasks** with one tap. Tap **More** to open the complete menu, grouped by workspace area where your role permits it. Selecting a page closes the sheet.\n\nThe highlighted item shows your current area. A project detail or closeout keeps **Projects** highlighted. Search, notifications, Help, and your account stay in the top bar. The exact options depend on your role and permissions.\n\n## Use the field portal navigation\nEmployees and subcontractors use **Employee Portal** as their field workspace. Its primary mobile actions are **Clock** when enabled, **Projects**, **Schedule**, **Tasks**, and **More**. Open **More** for the remaining enabled personal and operations sections, **Profile**, and **Warranty**. On desktop, use the Employee Portal sidebar.\n\nOwners, administrators, managers, and office staff who open **My Portal** remain in the office shell. They use a compact portal selector on desktop or a section list and Profile action on mobile; the page does not add a second global navigation bar. Entering a page address directly does not bypass role or module access.\n\n## Find help from any supported workspace\n1. Tap **Help** in the top navigation.\n2. Choose **Help Articles** for detailed instructions or **Quick answers & FAQ** for a short answer.\n3. Enter a screen name or a few useful words in the search field.\n4. Narrow the topic or article type if there are many matches.\n5. Open an article and use **Jump to section** to reach the part you need.\n\n## Work with forms and lists\nBefore saving, review fields above and below the keyboard. Close the keyboard when you need more room to inspect a form. Scroll within a table if a screen provides horizontal scrolling, and check that an action belongs to the intended row before tapping it.\n\nIf a list looks empty, clear its search, date, status, project, or assignee filters. A mobile section selector may replace desktop tabs; look for the selected section above the content.\n\n## Use AI Help comfortably\nTap the yellow **AI Help** button. On a phone, press and hold the widget, then drag it to a clear part of the screen. A normal tap opens it. Ask about one task at a time and include the page name. Close it to return to your work.\n\n## If the page is difficult to use\nSave or copy unfinished text before refreshing. Close an open More sheet or keyboard, then reopen the section. If a control still cannot be reached, note the page, device/browser, and what you were trying to do when contacting support. Leave private customer and payment details out of screenshots.","route":"/HelpArticles","search_terms":["mobile","phone","tablet","menu","navigation","keyboard","touch","small screen"],"priority":98,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-06","article_type":"guide","read_minutes":2,"related_slugs":["guide-navigation-search","guide-troubleshooting"],"source_key":"help_articles_portal"},{"slug":"guide-employee-portal","feature_area":"Employee Portal","audience":"all","question":"Find your personal work and HR tools in Employee Portal","answer_short":"Use the role-aware field portal on a phone or desktop, open Profile and Warranty, and understand why a module may be missing.","answer_long":"## What the field portal contains\n**Employee Portal** brings personal attendance, requests, assigned work, Profile, and support access together. The available sections depend on the company's plan, portal module settings, your role, and relevant work assignments. Clock In, timesheets, pay, time off, and expenses require a plan with HR access; the current upgrade screen identifies **Professional** as the required plan, and Business also includes HR access. Assigned projects, schedule, project notes, tasks, inventory, Profile, and Warranty do not require HR plan access.\n\nEmployees and subcontractors use the dedicated field portal. Your personal records are different from the company's office lists. A blank personal list may mean you have no matching records or assignments. Owners, administrators, managers, and office staff can open **My Portal** without leaving the office workspace.\n\n## Navigate on desktop\nField staff use the Employee Portal sidebar. **My information** can include **Clock In**, **My Timesheets**, **My Pay**, **My Time Off**, and **My Expenses**. **Operations** includes **My Projects**, **My Schedule**, **Project Notes**, **My Tasks**, and **Inventory**. **My Profile** is available from your identity card, and **Warranty** is under Support.\n\nOffice roles use a compact **My Portal** section selector rather than a second global sidebar. This keeps the office navigation available while showing the selected personal section.\n\n## Navigate on a phone\nFor field staff, the primary bottom bar is **Clock** when enabled, **Projects**, **Schedule**, **Tasks**, and **More**. Open **More** for the remaining enabled information and operations sections, **Profile**, and **Warranty**. Selecting an item closes the menu. Office roles use the normal office bottom bar and a compact portal section selector inside My Portal.\n\n## Understand missing modules and protected links\nAn owner or administrator controls portal modules in **Settings → Employee Portal**. Clock In/Out, Timesheets, My Pay, Time Off, Expenses, Daily Logs, Tasks, and Inventory can each be enabled or disabled. My Projects, My Schedule, Profile, and Warranty remain portal destinations, while assignments and route permissions determine the records or pages you may use.\n\nIf a module is disabled, opening its saved or copied portal URL shows it as unavailable instead of loading its content. Entering another page address directly does not bypass role, module, or assignment access. Ask the office to check the plan, saved switches, your role, and assignment before assuming the account is broken.\n\n## Work without duplicate entries\nOpen the right section and review existing history before submitting another timesheet, expense, or material checkout. Wait for the success or error message after saving. On a slow mobile connection, repeated taps can create extra records.\n\n## Update your profile or recover from an error\nOpen **Profile** to update your own full name and phone number. Your administrator manages your role, pay rate, and account access. Check that your login belongs to the correct company. Use **Retry** where offered, or sign in again if your session expired. If access still looks wrong, give your administrator the page name and error without sharing a password or private link.","route":"/EmployeePortal","search_terms":["employee portal","field portal","missing tabs","more menu","professional plan","staff portal"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-06","article_type":"guide","read_minutes":2,"related_slugs":["guide-clock-in-out","guide-field-assigned-work"],"source_key":"help_articles_portal"},{"slug":"guide-portal-module-settings","feature_area":"Settings","audience":"admin","question":"Control which Employee Portal modules staff can see","answer_short":"Owners and administrators can separately enable Clock In/Out, Timesheets, Payroll, Time Off, Expenses, Daily Logs, Tasks, and Inventory.","answer_long":"## Who can change field modules\nOwners and administrators manage this in **Settings → Employee Portal**. Managers do not see the Employee Portal settings section. The company must have a plan with HR access; otherwise this section shows an upgrade wall rather than module controls.\n\nThese switches control which portal sections field workers can open on desktop and mobile. They are company settings, not personal preferences. Consider the work your staff need to complete before hiding an active workflow.\n\n## Review the individual switches\nUnder **Time & Attendance**, configure **Clock In & Out**, **Timesheets**, **My Pay**, and **Time Off** separately. The remaining switches are **Expense Tracking**, **Daily Logs & Project Notes**, **Task Assignments**, and **Inventory Checks**. This lets the company expose only the personal tools required for each workflow.\n\n**My Projects**, **My Schedule**, **My Profile**, and **Warranty** are not controlled by these eight switches. Assignments, plan access, role permissions, and saved records determine what those destinations contain or allow.\n\n## Save a module change\n1. Open Settings and choose Employee Portal.\n2. Review every switch under **Active Modules**.\n3. Turn the intended module on or off.\n4. Select **Save Module Settings**.\n5. Wait for confirmation before leaving the page.\n6. Ask a staff member with the appropriate role to refresh their portal and verify the intended section is visible or unavailable.\n\nDisabling a module removes its navigation action and blocks its portal content; it does not delete existing time entries, expenses, tasks, or inventory transactions. Re-enabling a section does not create records or assignments for staff who have none.\n\n## Explain navigation to staff\nOn a phone, field staff see **Clock** when enabled, **Projects**, **Schedule**, **Tasks**, and **More**. Other enabled sections, **Profile**, and **Warranty** are inside More. On desktop, field staff use the Employee Portal sidebar. Owners, administrators, managers, and office staff use a compact **My Portal** selector inside the normal office shell rather than a second global menu.\n\nIf a portal link is bookmarked, disabling its module still prevents the content from loading. Direct URLs do not override role, module, or assignment checks. Check the saved switch, plan access, active account, company membership, and any project or task assignment.\n\n## Troubleshooting\nIf a change does not persist, return to the section and check whether the save succeeded. Use the correct company account and record any permission or network error. Avoid disabling Clock In & Out while staff have active shifts without arranging how they will complete those records.","route":"/AdminSettings","search_terms":["employee modules","enable time clock","missing portal tab","feature toggles","attendance","portal settings"],"priority":75,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-06","article_type":"guide","read_minutes":2,"related_slugs":["guide-employee-portal","guide-team-access-and-seats"],"source_key":"help_articles_portal"},{"slug":"employee-portal-features","feature_area":"Employee Portal","audience":"all","question":"What can employees access in the Employee Portal?","answer_short":"The Employee Portal provides personal attendance, assigned work, expenses, project notes, tasks, inventory, Profile, and Warranty access where the plan and company modules allow.","answer_long":"Open **Employee Portal** for your personal field tools. Available sections depend on the company’s plan, your role, assigned work, and the company’s enabled portal modules.\n\n- Personal tools can include **Clock In**, **My Timesheets**, **My Pay**, **My Time Off**, and **My Expenses**.\n- Work tools include **My Projects**, **My Schedule**, **Project Notes**, **My Tasks**, and **Inventory**.\n- **My Profile** lets you update your own name and phone number. Your administrator manages your role, pay rate, and account access. **Warranty** is available from the portal’s Support area.\n\nOn a phone, the primary field navigation is **Clock** when enabled, **Projects**, **Schedule**, **Tasks**, and **More**. Open **More** for the remaining personal and work sections, **Profile**, and **Warranty**. On desktop, use the Employee Portal sidebar.\n\nIf a section is missing, ask an owner or administrator to check **Settings → Employee Portal**, the company’s plan, your role, and any required project or task assignment. Entering a page address directly does not bypass role, module, or assignment access.","route":"/EmployeePortal","search_terms":["employee portal","clock in","timesheet","time off","expenses","profile setup","more menu"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-06","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"mobile-office-navigation","feature_area":"Help & Support","audience":"all","question":"Where is the office menu on mobile?","answer_short":"Office roles use Dashboard, Leads, Projects, Tasks, and More; field roles use Clock when enabled, Projects, Schedule, Tasks, and More.","answer_long":"On a phone, owners, administrators, managers, and office staff use the office bottom bar for one-tap access to **Dashboard**, **Leads**, **Projects**, and **Tasks**. Tap **More** to open every other page allowed by your role, grouped by workspace area. Selecting a destination closes the More sheet.\n\nEmployees and subcontractors use the field portal instead of the office navigation. Its primary mobile actions are **Clock** when enabled, **Projects**, **Schedule**, **Tasks**, and **More**. Open **More** for other enabled modules, **Profile**, and **Warranty**. On desktop, field staff use the Employee Portal sidebar.\n\nSearch, notifications, Help, and the account menu remain in the top bar. Owners, administrators, managers, and office staff who open **My Portal** keep the normal office workspace and use a compact portal section selector instead of receiving a second sidebar or bottom bar.\n\nIf a destination is missing, ask a company administrator to check your role, module settings, and permissions. Changing the URL does not grant access. The bottom bars reserve space below page content, including the device safe area, so they should not cover the last form controls.","route":"/HelpArticles","search_terms":["mobile menu","hamburger","bottom navigation","More","Dashboard Leads Projects Tasks","missing menu"],"priority":80,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-06","article_type":"faq","read_minutes":1,"related_slugs":[],"source_key":"help_articles_faq_correction"}]$articles$::jsonb)
AS a(slug text,feature_area text,audience text,question text,answer_short text,answer_long text,route text,search_terms text[],priority smallint,requires_admin boolean,is_active boolean,last_verified_at date,article_type text,read_minutes smallint,related_slugs text[],source_key text)
ON CONFLICT (slug) DO UPDATE SET
 feature_area=EXCLUDED.feature_area,
 audience=EXCLUDED.audience,
 question=EXCLUDED.question,
 answer_short=EXCLUDED.answer_short,
 answer_long=EXCLUDED.answer_long,
 route=EXCLUDED.route,
 search_terms=EXCLUDED.search_terms,
 priority=EXCLUDED.priority,
 requires_admin=EXCLUDED.requires_admin,
 is_active=EXCLUDED.is_active,
 last_verified_at=EXCLUDED.last_verified_at,
 article_type=EXCLUDED.article_type,
 read_minutes=EXCLUDED.read_minutes,
 related_slugs=EXCLUDED.related_slugs,
 source_key=EXCLUDED.source_key,
 embedding=CASE WHEN (help_faqs.question,help_faqs.answer_short,help_faqs.answer_long) IS NOT DISTINCT FROM (EXCLUDED.question,EXCLUDED.answer_short,EXCLUDED.answer_long) THEN help_faqs.embedding ELSE NULL END;
